// The studio HUD. Scripts send what the HUD shows inside the title text, behind an invisible prefix:
// RP/ui/hud_screen.json (generated by tools/gen_hud.py) draws it as stone & gold panels and hides the plain title.
// Toasts (big moments: crafted, quest done, warnings) ride in the subtitle and get their own banner. Every title goes
// through this module, so the HUD and the toasts never fight over the screen.
import { system } from '@minecraft/server';

/** Invisible prefixes (formatting codes) - must match tools/gen_hud.py. */
export const HUD_CODES = { home: '§h§u§1', run: '§h§u§2', toast: '§t§q§s' };
const SEGMENTS = '123456789a';
/** Light bar level 0..10 inside a run HUD text: one mark per lit segment (the HUD tests each mark on its own). */
export const levelMark = (n) => [...SEGMENTS.slice(0, Math.max(0, Math.min(10, n)))].map((c) => `§q§q§${c}`).join('');

const toasts = new Map(); // playerId -> { text, until }
const shown = new Map(); // playerId -> the HUD title last sent
const sentAt = new Map(); // playerId -> tick it was sent (re-sent every few seconds so it never runs out)

function send(player, title) {
  const toast = toasts.get(player.id);
  const live = toast && system.currentTick < toast.until;
  if (toast && !live) toasts.delete(player.id);
  sentAt.set(player.id, system.currentTick);
  try {
    player.onScreenDisplay.setTitle(title, { fadeInDuration: 0, stayDuration: 400, fadeOutDuration: 0, subtitle: live ? toast.text : ' ' });
  } catch {
    // the player is leaving or not loaded yet
  }
}

/** Show the HUD: mode 'home' or 'run', text with \n between lines; level (0..10) fills the light bar of a run. */
export function showHud(player, mode, text, level) {
  const title = HUD_CODES[mode] + (level === undefined ? '' : levelMark(level)) + text;
  if (shown.get(player.id) === title && !toasts.has(player.id) && system.currentTick - (sentAt.get(player.id) ?? -999) < 100) return;
  shown.set(player.id, title);
  send(player, title);
}

/** A banner under the HUD for a few seconds: a gold title line and an optional second line. */
export function toast(player, title, line = '', seconds = 3.5) {
  const until = system.currentTick + Math.round(seconds * 20);
  toasts.set(player.id, { text: `${HUD_CODES.toast}§6${title}${line ? `\n§f${line}` : ''}`, until });
  send(player, shown.get(player.id) ?? ' ');
  system.runTimeout(() => {
    if (player.isValid && toasts.get(player.id)?.until === until) send(player, shown.get(player.id) ?? ' ');
  }, until - system.currentTick + 1);
}

/** No HUD (not playing a session). */
export function clearHud(player) {
  shown.delete(player.id);
  send(player, ' ');
}

export function forgetHud(playerId) {
  toasts.delete(playerId);
  shown.delete(playerId);
  sentAt.delete(playerId);
}
